/**
 * GameState — 唯一状态源 (Single Source of Truth)
 *
 * 所有游戏数据集中在此对象中。每个模块通过 getState()/updateState() 读写。
 * 使用 Proxy 实现变更追踪（dirty flag），驱动按需渲染。
 */

// ====== 默认初始状态 ======
function createDefaultState() {
  const now = Date.now();
  return {
    // --- 元数据 ---
    version: "1.0.0",
    createdAt: now,
    lastPlayedAt: now,
    playTime: 0,

    // --- 玩家身份 ---
    player: {
      name: "无名",
      gender: "male",
      age: 20,
      birthday: { month: 6, day: 15 },

      // 街头 4 维属性 (0-100)
      physique: 22, // 体质
      intelligence: 20, // 智力
      agility: 24, // 敏捷
      mental: 26, // 心智

      // 职场 7 维属性 (进入职场后初始化)
      corporate: {
        hair: 100,
        dignity: 60,
        upwardMgmt: 20,
        kpi: 20,
        ability: 30,
        risk: 0,
        popularity: 30,
      },

      // 阶段与时间
      phase: "street", // 'street' | 'corporate'
      day: 1,
      corpYear: 0, // 入职年数
      corpQuarter: 1, // 1-4
      timeSlot: "morning", // 'morning' | 'afternoon' | 'evening' (显示用)
      actionPoints: 100, // 当前行动力 (0-100)
      maxActionPoints: 100, // 每日行动力上限
    },

    // --- 经济 ---
    resources: {
      cash: 1500, // 现金（元）
      bankBalance: 0, // 银行存款
      debt: 5500, // 当前总欠款（兼容旧字段）
      villageDebt: 5500, // 欠村长的钱
      villageDebtInterest: 0, // 累计村长利息
      bankDebt: 0, // 欠银行的钱
      loanPrincipal: 5500, // 原始借款额
      loanDay: 0, // 借款日
      dailyInterest: 0.0035, // 日息 0.3%
